下面是一段约 30 行的 Python 代码。请把其中所有 snake_case 变量名改成 camelCase，字符串字面量和 key 保持不变，逻辑完全不变，只输出改完的代码：

def build_report(raw_rows, user_name, is_debug):
    total_count = 0
    error_count = 0
    result_list = []
    for row_index, current_row in enumerate(raw_rows):
        if current_row is None:
            error_count = error_count + 1
            continue
        clean_value = str(current_row).strip()
        if len(clean_value) == 0:
            error_count = error_count + 1
            continue
        total_count = total_count + 1
        entry_record = {
            "row_index": row_index,
            "clean_value": clean_value,
            "value_length": len(clean_value),
        }
        result_list.append(entry_record)
    summary_block = {
        "user_name": user_name,
        "total_count": total_count,
        "error_count": error_count,
    }
    if is_debug:
        summary_block["debug_flag"] = True
    report_object = {
        "summary_block": summary_block,
        "result_list": result_list,
    }
    return report_object


if __name__ == "__main__":
    sample_rows = ["a", None, "  ", "bb", "ccc"]
    print(build_report(sample_rows, "tester", True))

